import jdk.jfr.consumer.*;
import java.nio.file.*;
import java.util.*;

public class JfrAgg {
    public static void main(String[] a) throws Exception {
        Map<String, Integer> self = new HashMap<>(), incl = new HashMap<>();
        int total = 0;
        try (RecordingFile rf = new RecordingFile(Paths.get(a[0]))) {
            while (rf.hasMoreEvents()) {
                RecordedEvent e = rf.readEvent();
                if (!e.getEventType().getName().equals("jdk.ExecutionSample")) continue;
                RecordedStackTrace st = e.getStackTrace();
                if (st == null || st.getFrames().isEmpty()) continue;
                total++;
                List<RecordedFrame> fs = st.getFrames();
                String top = name(fs.get(0));
                self.merge(top, 1, Integer::sum);
                Set<String> seen = new HashSet<>();
                for (RecordedFrame f : fs) { String n = name(f); if (seen.add(n)) incl.merge(n, 1, Integer::sum); }
            }
        }
        int k = a.length > 1 ? Integer.parseInt(a[1]) : 25;
        System.out.println("samples " + total);
        System.out.println("== self");
        self.entrySet().stream().sorted((x, y) -> y.getValue() - x.getValue()).limit(k)
            .forEach(x -> System.out.printf("%6d %5.1f%% %s%n", x.getValue(), 100.0 * x.getValue() / total, x.getKey()));
        System.out.println("== inclusive");
        incl.entrySet().stream().sorted((x, y) -> y.getValue() - x.getValue()).limit(k)
            .forEach(x -> System.out.printf("%6d %5.1f%% %s%n", x.getValue(), 100.0 * x.getValue() / total, x.getKey()));
        for (int i = 2; i < a.length; i++) {
            String w = a[i]; int n = 0;
            for (Map.Entry<String,Integer> x : incl.entrySet()) if (x.getKey().contains(w)) n = Math.max(n, x.getValue());
            System.out.printf("== match %s: %d %5.1f%%%n", w, n, 100.0 * n / total);
        }
    }
    static String name(RecordedFrame f) {
        RecordedMethod m = f.getMethod();
        return m.getType().getName() + "." + m.getName();
    }
}
