import jdk.jfr.consumer.*;
import java.nio.file.*;
import java.util.*;

public class JfrCallees {
    // usage: JfrCallees <file> <method substring> [depth]: for samples whose stack holds the method,
    // the distribution of the frames at 1..depth levels below its outermost occurrence
    public static void main(String[] a) throws Exception {
        String w = a[1]; int depth = a.length > 2 ? Integer.parseInt(a[2]) : 1;
        List<Map<String,Integer>> lv = new ArrayList<>(); for (int i = 0; i < depth; i++) lv.add(new HashMap<>());
        int n = 0;
        try (RecordingFile rf = new RecordingFile(Paths.get(a[0]))) {
            while (rf.hasMoreEvents()) {
                RecordedEvent e = rf.readEvent();
                if (!e.getEventType().getName().equals("jdk.ExecutionSample")) continue;
                RecordedStackTrace st = e.getStackTrace(); if (st == null) continue;
                List<RecordedFrame> fs = st.getFrames();
                int at = -1;
                for (int i = fs.size() - 1; i >= 0; i--) if (name(fs.get(i)).contains(w)) { at = i; break; }
                if (at < 0) continue; n++;
                for (int d = 1; d <= depth; d++) { int j = at - d; String s = j >= 0 ? name(fs.get(j)) + ":" + fs.get(j).getLineNumber() : "(self)"; lv.get(d-1).merge(s, 1, Integer::sum); }
            }
        }
        System.out.println("samples with " + w + ": " + n);
        final int nn = n;
        for (int d = 0; d < depth; d++) { System.out.println("== level " + (d+1));
            lv.get(d).entrySet().stream().sorted((x, y) -> y.getValue() - x.getValue()).limit(12)
              .forEach(x -> System.out.printf("%6d %5.1f%% %s%n", x.getValue(), 100.0 * x.getValue() / nn, x.getKey())); }
    }
    static String name(RecordedFrame f) { RecordedMethod m = f.getMethod(); return m.getType().getName() + "." + m.getName(); }
}
